-- Variantes e quantidades de portfólio. As dimensões são estimativas de pacote.
-- O catálogo é carregado pelo script idempotente; esta migration é no-op em projetos vazios.
do $$
begin
  if exists (select 1 from public.products where id = '34118850-9af5-5cb6-bf07-1c80744a46f6'::uuid) then
    on conflict (id) do update set
      sku=excluded.sku,label=excluded.label,attributes=excluded.attributes,
      price_cents=excluded.price_cents,weight_grams=excluded.weight_grams,
      dimensions_mm=excluded.dimensions_mm,is_active=true;
  end if;
end $$;
